/**
 * Blog covers: real photos of our cars (generated by scripts/generate-images.js into /images/blog/).
 * Every post gets one automatically – the bot does not have to choose: posts about the convertible or summer get a
 * Cabrio photo, posts about winter/BMW 650i get the 650i, the rest a stable choice derived from the slug.
 */
const COVERS = {
  'bmw6-para': 'Białe BMW 650i Gran Coupé udekorowane na ślub, obok Para Młoda',
  'bmw6-fajerwerki': 'BMW 650i Gran Coupé i Para Młoda pod kurtyną fajerwerków',
  'bmw4-front': 'Białe BMW 4 Cabrio z dekoracją ślubną – widok z przodu',
  'bmw4-dach': 'BMW 4 Cabrio z otwartym dachem – auto do ślubu',
  'bmw4-willa': 'BMW 4 Cabrio przed willą weselną',
}
const ALL = Object.keys(COVERS)
const CABRIO = ['bmw4-dach', 'bmw4-front', 'bmw4-willa']
const BMW6 = ['bmw6-para', 'bmw6-fajerwerki']

function hash(text) {
  let h = 0
  for (const ch of text) h = (h * 31 + ch.charCodeAt(0)) >>> 0
  return h
}

/** `avoid` – cover id of the neighbouring card; lists pass it so two cards next to each other never repeat a photo. */
export function coverFor(post, avoid) {
  const text = `${post.slug} ${post.title}`.toLowerCase()
  const pool = /cabrio|kabriolet|lato|letni|wakacj|maj[oó]w/.test(text)
    ? CABRIO
    : /zim|grud|sylwest|andrzej|650i|gran coup|fajerwerk|wieczor/.test(text)
      ? BMW6
      : ALL
  let index = hash(post.slug) % pool.length
  if (pool[index] === avoid) index = (index + 1) % pool.length
  const id = pool[index]
  const base = `/images/blog/cover-${id}`
  return {
    id,
    alt: COVERS[id],
    small: `${base}-600.jpg`,
    smallWebp: `${base}-600.webp`,
    large: `${base}-1200.jpg`,
    largeWebp: `${base}-1200.webp`,
  }
}
